const items = $input.all();
const results = [];

for (const entry of items) {
    const body = entry.json.body || entry.json;
    const rawApp = (body.app || '').toLowerCase();
    const title = (body.title || '').trim();
    const text = (body.text || '').trim();
    const fullText = `${title} ${text}`.replace(/\s+/g, ' ');
    const lower = fullText.toLowerCase();

    // 1. Descartar avisos de marketing, promociones, referidos y avisos administrativos
    const ignoreKeywords = [
        'preaprobado', 'crédito disponible', 'solicita', 'invita', 'amigo', 'amigos',
        'tu link', 'gana ', 'ganar', 'gana hasta', 'gana $', 'gana dinero',
        'actualiza', 'contraseña', 'código de seguridad', 'token', 'iniciaste sesión',
        'bloqueada', 'desbloqueada', 'promoción', 'promocion', 'cashback disponible',
        'descuento', 'cupón', 'cupon', 'sorteo', 'premio', 'recomienda', 'refiere',
        'aprovecha', 'disfruta de', 'conoce más', 'contrata', 'felicidades'
    ];
    if (ignoreKeywords.some(kw => lower.includes(kw))) {
        results.push({ json: { isValid: false, reason: 'Promoción, referido o aviso ignorado', fullText } });
        continue;
    }

    // 2. Debe contener verbos o palabras clave de transacción real
    const txActionRegex = /(compra|cargo|pagaste|pago|transferencia|transfiri|recibiste|recibida|abono|dep[oó]sito|spei|retiro|enviado|cobro)/i;
    if (!txActionRegex.test(lower)) {
        results.push({ json: { isValid: false, reason: 'No contiene acción transaccional válida', fullText } });
        continue;
    }

    // 3. Detectar Tipo (expense vs income)
    let type = 'expense';
    const isIncome = /(recibiste|recibida|abono|dep[oó]sito|te transfirieron|n[oó]mina|spei recibido)/i.test(lower);
    if (isIncome) {
        type = 'income';
    }

    // 4. Extraer Monto
    const amountRegex = /\$\s*([0-9]{1,3}(?:,[0-9]{3})*(?:\.[0-9]{1,2})?)|([0-9]{1,3}(?:,[0-9]{3})*\.[0-9]{2})\s*(?:mn|mxn|pesos)?/i;
    const amountMatch = fullText.match(amountRegex);
    if (!amountMatch) {
        results.push({ json: { isValid: false, reason: 'Sin monto detectable', fullText } });
        continue;
    }
    const rawAmountStr = amountMatch[1] || amountMatch[2];
    const amount = parseFloat(rawAmountStr.replace(/,/g, ''));
    if (isNaN(amount) || amount <= 0) {
        results.push({ json: { isValid: false, reason: 'Monto inválido', fullText } });
        continue;
    }

    // 5. Identificar Banco
    let bank = 'General';
    if (rawApp.includes('bbva') || /\bbbva\b/i.test(lower)) bank = 'BBVA';
    else if (rawApp.includes('nu') || /\bnu\b/i.test(lower)) bank = 'Nu';
    else if (rawApp.includes('mercado') || /mercado pago/i.test(lower)) bank = 'Mercado Pago';
    else if (rawApp.includes('santander') || /\bsantander\b/i.test(lower)) bank = 'Santander';
    else if (rawApp.includes('banorte') || /\bbanorte\b/i.test(lower)) bank = 'Banorte';
    else if (rawApp.includes('azteca') || /banco azteca/i.test(lower)) bank = 'Banco Azteca';
    else if (rawApp.includes('hey') || /hey banco/i.test(lower)) bank = 'Hey Banco';

    // 6. Extraer Comercio / Descripción
    let description = '';
    const enMatch = fullText.match(/\ben\s+([A-Za-z0-9\s\.\*\-\_\&]{2,35}?)(?=\s+(?:con|el|aprobada|T\.|cuenta|\*|\.|\,|$))/i);
    if (enMatch && enMatch[1]) {
        description = enMatch[1].trim();
    }
    if (!description && isIncome) {
        const deMatch = fullText.match(/\bde\s+([A-Za-z0-9\s\.\*\-\_\&]{2,35}?)(?=\s+(?:el|cuenta|\*|\.|\,|$))/i);
        if (deMatch && deMatch[1]) {
            description = `De: ${deMatch[1].trim()}`;
        }
    }
    if (!description || description.length < 3) {
        description = `${bank}: ${text.slice(0, 45)}`;
    }

    // 7. Asignar Categoría
    let category = 'Varios';
    const descLower = description.toLowerCase();
    if (/(walmart|soriana|heb|oxxo|chedraui|bodega|costco|sams|super|tienda|abarrotes)/i.test(descLower)) category = 'Super y Despensa';
    else if (/(uber|didi|gasolina|pemex|bp|shell|g500|estacionamiento|peaje|tag)/i.test(descLower)) category = 'Transporte';
    else if (/(cfe|telcel|telmex|izzi|agua|gas|naturgy|at&t|totalplay)/i.test(descLower)) category = 'Servicios';
    else if (/(starbucks|mcdonalds|kfc|pizza|restaurante|cafe|tacos|comida|burger|sushi|subway|vips)/i.test(descLower)) category = 'Comida';
    else if (/(netflix|spotify|disney|prime|youtube|apple|hbo|crunchyroll)/i.test(descLower)) category = 'Suscripciones';
    else if (/(farmacia|guadalajara|ahorro|san pablo|benavides|medico|hospital|laboratorio)/i.test(descLower)) category = 'Salud';
    else if (type === 'income') category = 'Ingresos';

    results.push({
        json: {
            isValid: true,
            bank,
            amount,
            type,
            description,
            category,
            date: new Date().toISOString(),
            originalText: fullText
        }
    });
}

return results;
